typedef struct DNode {
  int val;
  struct DNode *prev, *next;
} DNode;

DNode *head = NULL, *tail = NULL;

/* insert n after node p (p != NULL) */
void insert_after(DNode *p, DNode *n) {
  n->prev = p; n->next = p->next;
  if (p->next) p->next->prev = n;
  p->next = n;
}
/* push at front */
void push_front(DNode **head, DNode *n) {
  n->prev = NULL; n->next = *head;
  if (*head) (*head)->prev = n;
  *head = n;
}

void unlink_node(DNode **head, DNode *n) {
  if (n->prev) n->prev->next = n->next; else *head = n->next;
  if (n->next) n->next->prev = n->prev;
  free(n);
}
